int main(int argc, char const *argv[])
{
  UnoQFilterPlugin plugin;
  json params;
  json input, output;

  // Set example values to params
  params["socket_path"] = "/tmp/mads-rpc.sock";
  params["verbose"] = true;

  // Set the parameters
  plugin.set_params(params);

  // Set input data
  input["rpc_func"] = "echo";
  input["rpc_args"] = {
    42,
    "hello",
    true
  };

  // Set input data
  plugin.load_data(input);
  cout << "Input: " << input.dump(2) << endl;

  // Process data
  plugin.process(output);
  cout << "Output: " << output.dump(2) << endl;


  return 0;
}

